<?php require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/auth.php';require_login();$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user']['id']]);$orders=$s->fetchAll();$pageTitle='My Orders';include __DIR__.'/../includes/partials/header.php';?><h1>My Orders</h1><?php foreach($orders as $o):?><div class="order-card"><h3><?=e($o['order_code'])?></h3><p><?=e($o['status'])?> · <?=e($o['created_at'])?></p><strong>Rs <?=number_format($o['total'],2)?></strong> <a href="tracking.php?code=<?=urlencode($o['order_code'])?>">Track</a></div><?php endforeach;if(!$orders):?><p>No orders yet.</p><?php endif;?><?php include __DIR__.'/../includes/partials/footer.php';?>